create schema private; create schema auth; create role authenticated; create role anon;
create function auth.uid() returns uuid language sql as 'select null::uuid';
create function private.is_clinic_staff(uuid) returns boolean language sql as 'select true';
create table clinics(id uuid primary key);
create table patients(id uuid primary key,clinic_id uuid,birth_date date);
create table clinical_plans(id uuid primary key default gen_random_uuid(),clinic_id uuid,patient_id uuid,status text,source_odontogram_version int,version int,created_at timestamptz default now(),updated_at timestamptz default now());
create table treatment_catalog(id uuid default gen_random_uuid(),clinic_id uuid,code text,name text,specialty text,category text,default_price_cents int,base_cost_cents int,active boolean,metadata jsonb default '{}',unique(clinic_id,code));
create table dental_entities(id uuid primary key default gen_random_uuid(),patient_id uuid,tooth text,arch text,entity_type text,status text,active boolean,attributes_json jsonb,surfaces_json jsonb,version int default 1,created_at timestamptz default now());
create table clinical_plan_items(id uuid primary key default gen_random_uuid(),clinic_id uuid,plan_id uuid,dental_entity_id uuid,tooth text,treatment_code text,label text,patient_label text,clinical_reason text,phase int,priority int,status text,price_cents int,attributes_json jsonb default '{}',treatment_catalog_id uuid,treatment_code_snapshot text,label_snapshot text,price_snapshot_cents int,cost_snapshot_cents int,treatment_metadata_snapshot jsonb,is_ad_hoc boolean,created_at timestamptz default now());
create table clinical_history_events(clinic_id uuid,patient_id uuid,actor_id uuid,event_type text,entity_id uuid,entity_type text,payload_json jsonb);
create function public.refresh_consent_requirements(uuid) returns void language sql as 'select';
insert into clinics values('00000000-0000-4000-8000-000000000001');
insert into patients(id,clinic_id) values('00000000-0000-4000-8000-000000000002','00000000-0000-4000-8000-000000000001');
create table clinic_members(clinic_id uuid,profile_id uuid,active boolean,role text);
create table document_templates(id uuid default gen_random_uuid(),clinic_id uuid,code text,active boolean,version int);
create table documents(id uuid,patient_id uuid,template_id uuid,status text,signed_at timestamptz);
create table consent_requirements(clinic_id uuid,patient_id uuid,clinical_plan_item_id uuid,document_id uuid,consent_code text,status text,required_before text,template_id uuid,satisfied_by_document_id uuid,rule_version int,updated_at timestamptz default now());
create unique index consent_unique on consent_requirements(clinical_plan_item_id,consent_code) where clinical_plan_item_id is not null;
drop function public.refresh_consent_requirements(uuid);
create or replace function auth.uid() returns uuid language sql as $$select nullif(current_setting('request.jwt.claim.sub',true),'')::uuid$$;
create or replace function private.is_clinic_staff(uuid) returns boolean language sql security definer as $$ select exists(select 1 from public.clinic_members where clinic_id=$1 and profile_id=auth.uid() and active)$$;
grant usage on schema private,auth to authenticated;
grant select on patients,clinics,clinic_members to authenticated;
grant select,insert,update,delete on clinical_plans,clinical_plan_items,clinical_history_events,consent_requirements,treatment_catalog,dental_entities,document_templates,documents to authenticated;
insert into clinic_members values('00000000-0000-4000-8000-000000000001','00000000-0000-4000-8000-000000000003',true,'DENTIST');
